import React, { Component } from "react";
import { Link } from "react-router-dom";
import "./Signup.css";

export default class Signup extends Component {
    constructor(props) {
        super(props);
        this.state = {
            signupage: null,
        };
    }

    componentDidMount() {
        const pageName = "Signup";
        fetch(`http://localhost:3001/${pageName}`)
            .then(response => response.json())
            .then(page => {
                this.setState({ signupage: page });
            })
            .catch(error => console.error('Error fetching data:', error));
    }

    handleSubmit = (event) => {
        event.preventDefault();
        // Add your form submission logic here
        console.log('Form submitted');
    }

    render() {
        const { signupage } = this.state;
        const { onClose } = this.props;
        if (!signupage) return <div>PAGE NOT FOUND</div>;

        const textSignup = signupage.text;
        const leftsideContent = textSignup[0].leftside;
        const rightsideContent = textSignup[1].rightside;
        const buttonsdata = signupage.buttons;

        return (
            <div className="model-backdrop">
                <div className="content-container">
                    <Link to="#" className="close-button" onClick={onClose}>&times;</Link>
                    <div className="formbox">
                        <div className="button-box">
                            <div id="btn"></div>
                            {buttonsdata.map((value, index) => (
                                <button
                                    key={index}
                                    type={value.type}
                                    className={value.className}
                                >
                                    {value.text}
                                </button>
                            ))}
                        </div>

                        <div className="social-icons">
                            <img src={signupage.Img2} alt="Social Icon 1" />
                            <img src={signupage.Img1} alt="Social Icon 2" />
                        </div>

                        <form className="input-group" onSubmit={this.handleSubmit}>
                            <div className="input-left">
                                {leftsideContent.map((item, index) => (
                                    <input
                                        key={index}
                                        type={item.type}
                                        className={item.className}
                                        placeholder={item.placeholder}
                                        required
                                    />
                                ))}
                            </div>

                            <div className="input-right">
                                {rightsideContent.map((item, index) => (
                                    <input
                                        key={index}
                                        type={item.type}
                                        className={item.className}
                                        placeholder={item.placeholder}
                                        required
                                    />
                                ))}
                            </div>
                            <button type="submit" className="submit-btn">Sign up</button>
                        </form>
                    </div>
                </div>
            </div>
        );
    }
}
